// Node-RED Function Node: Delta Decompression Decoder with Register Mapping
// Decodes compressed delta records and applies scaling based on register addresses

// Register mapping with scaling factors
const REGISTER_MAP = {
    0: { name: 'Vac1_L1_Phase_voltage', gain: 10, unit: 'V' },
    1: { name: 'Iac1_L1_Phase_current', gain: 10, unit: 'A' },
    2: { name: 'Fac1_L1_Phase_frequency', gain: 100, unit: 'Hz' },
    3: { name: 'Vpv1_PV1_input_voltage', gain: 10, unit: 'V' },
    4: { name: 'Vpv2_PV2_input_voltage', gain: 10, unit: 'V' },
    5: { name: 'Ipv1_PV1_input_current', gain: 10, unit: 'A' },
    6: { name: 'Ipv2_PV2_input_current', gain: 10, unit: 'A' },
    7: { name: 'Inverter_internal_temperature', gain: 10, unit: '°C' },
    8: { name: 'Set_export_power_percentage', gain: 1, unit: '%' },
    9: { name: 'Pac_L_Inverter_current_output_power', gain: 1, unit: 'W' }
};

function get16_le(buffer, index) {
    if (index + 2 > buffer.length) return null;
    return buffer[index] | (buffer[index + 1] << 8);
}

function get32_le(buffer, index) {
    if (index + 4 > buffer.length) return null;
    return (buffer[index] |
        (buffer[index + 1] << 8) |
        (buffer[index + 2] << 16) |
        (buffer[index + 3] << 24)) >>> 0;
}

function get64_le(buffer, index) {
    if (index + 8 > buffer.length) return null;
    let low = get32_le(buffer, index);
    let high = get32_le(buffer, index + 4);
    return low + (high * 0x100000000);
}

function decodeRegister(address, rawValue) {
    const reg = REGISTER_MAP[address];

    if (!reg) {
        return {
            address: address,
            name: `Unknown_Register_${address}`,
            raw_value: rawValue,
            scaled_value: rawValue,
            unit: 'unknown'
        };
    }

    return {
        address: address,
        name: reg.name,
        raw_value: rawValue,
        scaled_value: rawValue / reg.gain,
        unit: reg.unit
    };
}

function decompressDelta(hexString) {
    const buffer = Buffer.from(hexString, 'hex');
    let i = 0;

    // Read header
    const base_ts = get64_le(buffer, i);
    if (base_ts === null) return null;
    i += 8;

    const nrecs = get16_le(buffer, i);
    if (nrecs === null) return null;
    i += 2;

    const records = [];
    let prev_ts = base_ts;

    // Process each record
    for (let r = 0; r < nrecs; r++) {
        const dt_ms = get32_le(buffer, i);
        if (dt_ms === null) return null;
        i += 4;

        const qty = get16_le(buffer, i);
        if (qty === null) return null;
        i += 2;

        const need = qty * 4;
        if (i + need > buffer.length) return null;

        const ts_ms = prev_ts + dt_ms;

        // Extract and decode register pairs
        const registers = {};
        for (let q = 0; q < qty; q++) {
            const addr = get16_le(buffer, i);
            const data = get16_le(buffer, i + 2);

            const decoded = decodeRegister(addr, data);
            registers[decoded.name] = {
                address: decoded.address,
                raw_value: decoded.raw_value,
                value: decoded.scaled_value,
                unit: decoded.unit
            };

            i += 4;
        }

        records.push({
            timestamp: ts_ms,
            register_count: qty,
            registers: registers
        });

        prev_ts = ts_ms;
    }

    return records;
}

// Main execution
try {
    const payload_hex = msg.payload.payload_hex;

    if (!payload_hex) {
        node.error("No payload_hex found in message");
        return null;
    }

    const decoded = decompressDelta(payload_hex);

    if (!decoded) {
        node.error("Failed to decompress delta data");
        return null;
    }

    // Create single output object with all data
    msg.payload = {
        type: msg.payload.type || 'delta_v1',
        total_records: decoded.length,
        compressed_bytes: msg.payload.compressed_bytes,
        records: decoded
    };

    return msg;

} catch (error) {
    node.error("Decoding error: " + error.message);
    return null;
}

