/**
 * Extract Vac1 - L1 Phase Voltage
 */
function extractVac1(records) {
    const data = [];
    records.forEach(record => {
        const reg = record.registers['Vac1_L1_Phase_voltage'];
        if (reg) {
            data.push({
                timestamp: record.timestamp,
                time: new Date(record.timestamp).toISOString(),
                value: reg.value,
                unit: reg.unit
            });
        }
    });
    return { name: 'Vac1_L1_Phase_voltage', data };
}

